16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "title")
39	    private String title;
40	
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "address_line1")
46	    private String addressLine1;
47	
48	    @Column(name = "address_line2")
49	    private String addressLine2;
50	
51	    @Column(name = "city")
52	    @NotEmpty
53	    private String city;
54	
55	    @Column(name = "telephone")
56	    @NotEmpty
57	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
58	    private String telephone;
59	
60	    @Column(name = "email")
61	    private String email;
62	
63	    @Column(name = "registration_date")
64	    private LocalDate registrationDate;
65	
66	    @Column(name = "birth_date")
67	    private LocalDate birthDate;
68	
69	    @Column(name = "customer_code")
70	    private String customerCode;
71	
72	    @Column(name = "household_id")
73	    private String householdId;
74	
75	    @Column(name = "namesake_count")
76	    private Integer namesakeCount;
77	
78	    @Column(name = "bulk_signup_warning")
79	    private Boolean bulkSignupWarning;
80	
81	    @Column(name = "household_size")
82	    private Integer householdSize;
83	
84	    @Column(name = "postcode")
85	    private String postcode;
86	
87	    @Column(name = "possible_duplicate")
88	    private Boolean possibleDuplicate;
89	
90	    @Column(name = "possible_duplicate_of")
91	    private Integer possibleDuplicateOf;
92	
93	    @Transient
94	    private boolean declaredHouseholdMember;
95	
96	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
97	    private Set<Pet> pets;
98	
99	    public String getTitle() {
100	        return this.title;
101	    }
102	
103	    public void setTitle(String title) {
104	        this.title = title;
105	    }
106	
107	    /**
108	     * The owner's salutation: the {@link #getTitle() title} and last name separated by a
109	     * single space (e.g. {@code "DR Who"}), or just the last name when no title is on file.
110	     * Derived from the owner's own fields, so it stays consistent with them.
111	     */
112	    @Transient
113	    public String getSalutation() {
114	        if (this.title == null || this.title.isEmpty()) {
115	            return this.getLastName();
116	        }
117	        return this.title + " " + this.getLastName();
118	    }
119	
120	    public String getAddress() {
121	        return this.address;
122	    }
123	
124	    public void setAddress(String address) {
125	        this.address = address;
126	    }
127	
128	    public String getAddressLine1() {
129	        return this.addressLine1;
130	    }
131	
132	    public void setAddressLine1(String addressLine1) {
133	        this.addressLine1 = addressLine1;
134	    }
135	
136	    public String getAddressLine2() {
137	        return this.addressLine2;
138	    }
139	
140	    public void setAddressLine2(String addressLine2) {
141	        this.addressLine2 = addressLine2;
142	    }
143	
144	    public String getCity() {
145	        return this.city;
146	    }
147	
148	    public void setCity(String city) {
149	        this.city = city;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    public String getEmail() {
161	        return this.email;
162	    }
163	
164	    public void setEmail(String email) {
165	        this.email = email;
166	    }
167	
168	    public LocalDate getRegistrationDate() {
169	        return this.registrationDate;
170	    }
171	
172	    public void setRegistrationDate(LocalDate registrationDate) {
173	        this.registrationDate = registrationDate;
174	    }
175	
176	    public LocalDate getBirthDate() {
177	        return this.birthDate;
178	    }
179	
180	    public void setBirthDate(LocalDate birthDate) {
181	        this.birthDate = birthDate;
182	    }
183	
184	    public String getCustomerCode() {
185	        return this.customerCode;
186	    }
187	
188	    public void setCustomerCode(String customerCode) {
189	        this.customerCode = customerCode;
190	    }
191	
192	    public String getHouseholdId() {
193	        return this.householdId;
194	    }
195	
196	    public void setHouseholdId(String householdId) {
197	        this.householdId = householdId;
198	    }
199	
200	    public Integer getNamesakeCount() {
201	        return this.namesakeCount;
202	    }
203	
204	    public void setNamesakeCount(Integer namesakeCount) {
205	        this.namesakeCount = namesakeCount;
206	    }
207	
208	    public Boolean getBulkSignupWarning() {
209	        return this.bulkSignupWarning;
210	    }
211	
212	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
213	        this.bulkSignupWarning = bulkSignupWarning;
214	    }
215	
216	    public Integer getHouseholdSize() {
217	        return this.householdSize;
218	    }
219	
220	    public void setHouseholdSize(Integer householdSize) {
221	        this.householdSize = householdSize;
222	    }
223	
224	    public String getPostcode() {
225	        return this.postcode;
226	    }
227	
228	    public void setPostcode(String postcode) {
229	        this.postcode = postcode;
230	    }
231	
232	    /**
233	     * Whether this owner deliberately declared, when created, that it shares its
234	     * household with an existing owner (the request's {@code sharesHousehold} flag).
235	     * A declared member is created despite occupying an existing household and is not
236	     * treated as a suspected duplicate. This is a request-scoped flag, not persisted.
237	     */
238	    @Transient
239	    public boolean isDeclaredHouseholdMember() {
240	        return this.declaredHouseholdMember;
241	    }
242	
243	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
244	        this.declaredHouseholdMember = declaredHouseholdMember;
245	    }
246	
247	    /**
248	     * Whether this owner, when created, was found to be a possible (soft) duplicate of an
249	     * existing owner: not a hard duplicate, but sharing that owner's last name and postcode
250	     * while carrying a different telephone. See {@link #getPossibleDuplicateOf()}.
251	     */
252	    public Boolean getPossibleDuplicate() {
253	        return this.possibleDuplicate;
254	    }
255	
256	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
257	        this.possibleDuplicate = possibleDuplicate;
258	    }
259	
260	    /**
261	     * The id of the existing owner this owner was flagged as a possible duplicate of, or
262	     * null when it is not a possible duplicate. See {@link #getPossibleDuplicate()}.
263	     */
264	    public Integer getPossibleDuplicateOf() {
265	        return this.possibleDuplicateOf;
266	    }
267	
268	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
269	        this.possibleDuplicateOf = possibleDuplicateOf;
270	    }
271	
272	    /**
273	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
274	     * is the last two digits of the registration date's year (e.g. {@code "NSW-1A2B3C4D-M26"}).
275	     * Derived from the owner's own fields, so it stays consistent with them.
276	     */
277	    @Transient
278	    public String getMembershipNumber() {
279	        if (this.customerCode == null || this.registrationDate == null) {
280	            return null;
281	        }
282	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
283	    }
284	
285	    /**
286	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
287	     * over the digits of the customer code. Derived from the owner's own customer code,
288	     * so it stays consistent with it.
289	     */
290	    @Transient
291	    public Integer getCheckDigit() {
292	        if (this.customerCode == null) {
293	            return null;
294	        }
295	        return LuhnCheckDigit.of(this.customerCode);
296	    }
297	
298	    /**
299	     * The owner's membership points, starting at zero: two points are added when an email is
300	     * on file, one more when the owner is unique (namesake count of zero), two more for a
301	     * household of three or more, and three more when the owner has accrued more than a year of
302	     * tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays consistent
303	     * with them.
304	     */
305	    @Transient
306	    public Integer getMembershipPoints() {
307	        int points = 0;
308	        boolean hasEmail = this.email != null && !this.email.isEmpty();
309	        if (hasEmail) {
310	            points += 2;
311	        }
312	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
313	        if (unique) {
314	            points += 1;
315	        }
316	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
317	        if (largeHousehold) {
318	            points += 2;
319	        }
320	        boolean tenured = this.registrationDate != null
321	            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
322	        if (tenured) {
323	            points += 3;
324	        }
325	        return points;
326	    }
327	
328	    /**
329	     * The owner's membership level, a number from 1 to 4, derived from their
330	     * {@link #getMembershipPoints() membership points} (see {@link MembershipLevel}). Derived
331	     * from the owner's own fields, so it stays consistent with them.
332	     */
333	    @Transient
334	    public Integer getMembershipLevel() {
335	        return MembershipLevel.forPoints(getMembershipPoints());
336	    }
337	
338	    /**
339	     * The owner's locality: the canonical region, taken as the region segment of the
340	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
341	     * consistent with the owner's identity. When no customer code has been assigned yet
342	     * it falls back to resolving the region directly from the postcode and city (see
343	     * {@link RegionResolver}), the same rule the customer code itself is built from.
344	     */
345	    @Transient
346	    public String getLocality() {
347	        if (this.customerCode != null) {
348	            int separator = this.customerCode.indexOf('-');
349	            if (separator > 0) {
350	                return this.customerCode.substring(0, separator);
351	            }
352	        }
353	        return RegionResolver.regionFor(this.postcode, this.city);
354	    }
355	
356	    /**
357	     * The owner's timezone: the IANA timezone name for their {@link #getLocality() locality},
358	     * taken from the fixed region-to-timezone table (see {@link RegionTimezoneTable}), so it
359	     * stays consistent with the owner's region. Null when the locality has no known timezone.
360	     */
361	    @Transient
362	    public String getTimezone() {
363	        return RegionTimezoneTable.timezoneFor(getLocality());
364	    }
365	
366	    /**
367	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
368	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
369	     * stays consistent with them.
370	     */
371	    @Transient
372	    public String getContactPreference() {
373	        boolean hasEmail = this.email != null && !this.email.isEmpty();
374	        return hasEmail ? "EMAIL" : "PHONE";
375	    }
376	
377	    /**
378	     * The owner's telephone formatted for human display: the stored E.164 number
379	     * rendered as its country calling code, a space and the national digits grouped
380	     * in threes (e.g. {@code "+61 412 345 678"}). The raw {@link #getTelephone()}
381	     * stays in E.164 form. Derived from the owner's own telephone, so it stays
382	     * consistent with it. See {@link TelephoneFormatter}.
383	     */
384	    @Transient
385	    public String getTelephoneDisplay() {
386	        return TelephoneFormatter.toDisplay(this.telephone);
387	    }
388	
389	    /**
390	     * The owner's identity key: the single derived value used to detect duplicate owners,
391	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
392	     * Two owners are duplicates only when their whole identity keys are equal, so members
393	     * of one household (sharing a household id) but with different telephones stay distinct.
394	     * Derived from the owner's own fields, so it stays consistent with them.
395	     */
396	    @Transient
397	    public String getIdentityKey() {
398	        String telephonePart = this.telephone == null ? "" : this.telephone;
399	        String emailPart = this.email == null ? "" : this.email;
400	        String householdPart = this.householdId == null ? "" : this.householdId;
401	        return telephonePart + "|" + emailPart + "|" + householdPart;
402	    }
403	
404	    /**
405	     * The owner's age band relative to their registration date: {@code "MINOR"} when
406	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
407	     * Derived from the owner's own birth and registration dates, so it stays consistent
408	     * with them; null until a birth date is on file. See {@link AgeBand}.
409	     */
410	    @Transient
411	    public String getAgeBand() {
412	        if (this.birthDate == null || this.registrationDate == null) {
413	            return null;
414	        }
415	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
416	    }
417	
418	    /**
419	     * Normalize the registration date before persisting: default it to the server's
420	     * current date when none was supplied, then roll it forward onto a business day so
421	     * every newly persisted owner is registered on a weekday.
422	     */
423	    @PrePersist
424	    void normalizeRegistrationDate() {
425	        if (this.registrationDate == null) {
426	            this.registrationDate = LocalDate.now();
427	        }
428	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
429	    }
430	
431	    protected Set<Pet> getPetsInternal() {
432	        if (this.pets == null) {
433	            this.pets = new HashSet<>();
434	        }
435	        return this.pets;
436	    }
437	
438	    protected void setPetsInternal(Set<Pet> pets) {
439	        this.pets = pets;
440	    }
441	
442	    public List<Pet> getPets() {
443	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
444	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
445	        return Collections.unmodifiableList(sortedPets);
446	    }
447	
448	    public void setPets(List<Pet> pets) {
449	        this.pets = new HashSet<>(pets);
450	    }
451	
452	    public void addPet(Pet pet) {
453	        getPetsInternal().add(pet);
454	        pet.setOwner(this);
455	    }
456	
457	    /**
458	     * Return the Pet with the given name, or null if none found for this Owner.
459	     *
460	     * @param name to test
461	     * @return true if pet name is already in use
462	     */
463	    public Pet getPet(String name) {
464	        return getPet(name, false);
465	    }
466	
467	    /**
468	     * Return the Pet with the given name, or null if none found for this Owner.
469	     *
470	     * @param name to test
471	     * @return true if pet name is already in use
472	     */
473	    public Pet getPet(String name, boolean ignoreNew) {
474	        name = name.toLowerCase();
475	        for (Pet pet : getPetsInternal()) {
476	            if (!ignoreNew || !pet.isNew()) {
477	                String compName = pet.getName();
478	                compName = compName.toLowerCase();
479	                if (compName.equals(name)) {
480	                    return pet;
481	                }
482	            }
483	        }
484	        return null;
485	    }
486	
487	    public Pet getPet(Integer petId) {
488	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
489	    }
490	
491	    @Override
492	    public String toString() {
493	        return new ToStringCreator(this)
494	
495	            .append("id", this.getId())
496	            .append("new", this.isNew())
497	            .append("lastName", this.getLastName())
498	            .append("firstName", this.getFirstName())
499	            .append("address", this.address)
500	            .append("city", this.city)
501	            .append("telephone", this.telephone)
502	            .toString();
503	    }
504	}
