396	    @Transient
397	    public String getIdentityKey() {
398	        String telephonePart = this.telephone == null ? "" : this.telephone;
399	        String emailPart = this.email == null ? "" : this.email;
400	        String householdPart = this.householdId == null ? "" : this.householdId;
401	        return telephonePart + "|" + emailPart + "|" + householdPart;
402	    }
403	
404	    /**
405	     * The owner's age band relative to their registration date: {@code "MINOR"} when
406	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
407	     * Derived from the owner's own birth and registration dates, so it stays consistent
408	     * with them; null until a birth date is on file. See {@link AgeBand}.
409	     */
410	    @Transient
411	    public String getAgeBand() {
412	        if (this.birthDate == null || this.registrationDate == null) {
413	            return null;
414	        }
415	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
416	    }
417	
418	    /**
419	     * Normalize the registration date before persisting: default it to the server's
420	     * current date when none was supplied, then roll it forward onto a business day so
421	     * every newly persisted owner is registered on a weekday.
422	     */
423	    @PrePersist
424	    void normalizeRegistrationDate() {
425	        if (this.registrationDate == null) {
426	            this.registrationDate = LocalDate.now();
427	        }
428	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
429	    }
430	
431	    protected Set<Pet> getPetsInternal() {
432	        if (this.pets == null) {
433	            this.pets = new HashSet<>();
434	        }
435	        return this.pets;
436	    }
437	
438	    protected void setPetsInternal(Set<Pet> pets) {
439	        this.pets = pets;
440	    }
441	
442	    public List<Pet> getPets() {
443	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
444	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
445	        return Collections.unmodifiableList(sortedPets);
446	    }
447	
448	    public void setPets(List<Pet> pets) {
449	        this.pets = new HashSet<>(pets);
450	    }
451	
452	    public void addPet(Pet pet) {
453	        getPetsInternal().add(pet);
454	        pet.setOwner(this);
455	    }
456	
457	    /**
458	     * Return the Pet with the given name, or null if none found for this Owner.
459	     *
460	     * @param name to test
461	     * @return true if pet name is already in use
462	     */
463	    public Pet getPet(String name) {
464	        return getPet(name, false);
465	    }
466	
467	    /**
468	     * Return the Pet with the given name, or null if none found for this Owner.
469	     *
470	     * @param name to test
471	     * @return true if pet name is already in use
472	     */
473	    public Pet getPet(String name, boolean ignoreNew) {
474	        name = name.toLowerCase();
475	        for (Pet pet : getPetsInternal()) {
476	            if (!ignoreNew || !pet.isNew()) {
477	                String compName = pet.getName();
478	                compName = compName.toLowerCase();
479	                if (compName.equals(name)) {
480	                    return pet;
481	                }
482	            }
483	        }
484	        return null;
485	    }
486	
487	    public Pet getPet(Integer petId) {
488	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
489	    }
490	
491	    @Override
492	    public String toString() {
493	        return new ToStringCreator(this)
494	
495	            .append("id", this.getId())
496	            .append("new", this.isNew())
497	            .append("lastName", this.getLastName())
498	            .append("firstName", this.getFirstName())
499	            .append("address", this.address)
500	            .append("city", this.city)
501	            .append("telephone", this.telephone)
502	            .toString();
503	    }
504	}
