140	    /**
141	     * Normalize the owner's supplied address into its canonical stored form, preferring
142	     * the structured fields over the flat address. When a non-blank {@code addressLine1}
143	     * is supplied it wins: both structured lines are normalized and the stored
144	     * {@code address} becomes their composed value; otherwise the flat {@code address} is
145	     * normalized and used. The owner is left with a normalized structured/flat address.
146	     *
147	     * @param owner the owner whose address fields are normalized in place
148	     * @return {@code true} if the owner supplies an address in either form, {@code false}
149	     * when neither a structured nor a flat address was given
150	     */
151	    private boolean normalizeAddress(Owner owner) {
152	        String addressLine1 = addressNormalizer.normalize(owner.getAddressLine1());
153	        String addressLine2 = addressNormalizer.normalize(owner.getAddressLine2());
154	        String flatAddress = addressNormalizer.normalize(owner.getAddress());
155	        owner.setAddressLine2(addressNormalizer.isBlank(addressLine2) ? null : addressLine2);
156	        if (!addressNormalizer.isBlank(addressLine1)) {
157	            owner.setAddressLine1(addressLine1);
158	            owner.setAddress(addressNormalizer.compose(addressLine1, addressLine2));
159	            return true;
160	        }
161	        owner.setAddressLine1(null);
162	        if (!addressNormalizer.isBlank(flatAddress)) {
163	            owner.setAddress(flatAddress);
164	            return true;
165	        }
166	        return false;
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
172	        HttpHeaders headers = new HttpHeaders();
173	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
174	        if (!normalizeAddress(owner)) {
175	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
176	        }
177	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
178	        if (e164Telephone.isEmpty()) {
179	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
180	        }
181	        String telephone = e164Telephone.get();
182	        String email = emailNormalizer.normalize(owner.getEmail());
183	        if (email != null && (!emailNormalizer.isValid(email) || emailNormalizer.isDisposable(email))) {
184	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
185	        }
186	        if (owner.getPostcode() != null && !postcodeValidator.isValid(owner.getPostcode(), owner.getCity())) {
187	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
188	        }
189	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
190	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
191	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
192	        }
193	        LocalDate registrationDate = BusinessDay.rollForward(
194	            suppliedRegistrationDate == null ? LocalDate.now() : suppliedRegistrationDate);
195	        owner.setRegistrationDate(registrationDate);
196	        if (clinicService.countOwnersByRegistrationDate(registrationDate) >= MAX_OWNERS_PER_DAY) {
197	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
198	        }
199	        owner.setTelephone(telephone);
200	        owner.setEmail(email);
201	        if (clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
202	            return new ResponseEntity<>(HttpStatus.CONFLICT);
203	        }
204	        // The household is keyed on (last name, postcode): a second owner sharing both is a
205	        // household duplicate and is rejected, unless it declares 'sharesHousehold', which
206	        // bypasses this block and creates it as a (non-suspected) declared household member.
207	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
208	        if (!sharesHousehold && clinicService.isHouseholdOccupied(owner)) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        owner.setDeclaredHouseholdMember(sharesHousehold);
212	        this.clinicService.saveOwner(owner);
213	        this.ownerAuditLogger.logCreated(owner);
214	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
215	        headers.setLocation(UriComponentsBuilder.newInstance()
216	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
217	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
218	    }
