222	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
223	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
224	        if (currentOwner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        Optional<String> e164Telephone = telephoneNormalizer.toE164(ownerFieldsDto.getTelephone());
228	        if (e164Telephone.isEmpty()) {
229	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
230	        }
231	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
232	        if (email != null && (!emailNormalizer.isValid(email) || emailNormalizer.isDisposable(email))) {
233	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
234	        }
235	        String postcode = ownerFieldsDto.getPostcode();
236	        if (postcode != null && !postcodeValidator.isValid(postcode, ownerFieldsDto.getCity())) {
237	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
238	        }
239	        currentOwner.setAddress(ownerFieldsDto.getAddress());
240	        currentOwner.setCity(ownerFieldsDto.getCity());
241	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
242	        currentOwner.setLastName(ownerFieldsDto.getLastName());
243	        currentOwner.setTelephone(e164Telephone.get());
244	        currentOwner.setEmail(email);
245	        currentOwner.setPostcode(postcode);
246	        this.clinicService.saveOwner(currentOwner);
247	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
248	    }
