247	    @Override
248	    @Transactional
249	    public void saveOwner(Owner owner) throws DataAccessException {
250	        if (owner.isNew()) {
251	            if (owner.getCustomerCode() == null) {
252	                owner.setCustomerCode(customerCodeGenerator.generateUnique(
253	                    RegionResolver.regionFor(owner.getPostcode(), owner.getCity()),
254	                    owner.getTelephone(), owner.getLastName(),
255	                    ownerRepository::existsByCustomerCode));
256	            }
257	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
258	            owner.setBulkSignupWarning(
259	                ownerRepository.countByRegistrationDate(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
260	            owner.setHouseholdId(householdIdFor(owner));
261	            owner.setHouseholdSize(householdSizeIncluding(owner));
262	            Optional<Owner> possibleDuplicate = findPossibleDuplicate(owner);
263	            owner.setPossibleDuplicate(possibleDuplicate.isPresent());
264	            owner.setPossibleDuplicateOf(possibleDuplicate.map(Owner::getId).orElse(null));
265	        }
266	        ownerRepository.save(owner);
267	
268	    }
269	
270	    /**
271	     * The deterministic, shared household id this owner maps to, derived from its last
272	     * name and postcode so that owners sharing both belong to the same household.
273	     */
274	    private String householdIdFor(Owner owner) {
275	        return householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
276	    }
277	
278	    /**
279	     * Size of the household this new owner will belong to once persisted: the owners
280	     * already sharing its household id, plus the owner itself. An owner with no shared
281	     * household id stands alone, so its household size is one.
282	     */
283	    private int householdSizeIncluding(Owner owner) {
284	        if (owner.getHouseholdId() == null) {
285	            return 1;
286	        }
287	        return (int) ownerRepository.countByHouseholdId(owner.getHouseholdId()) + 1;
288	    }
289	
290	    /**
291	     * Count the existing owners that already share the given first and last name,
292	     * compared case-insensitively. Used to stamp a new owner's namesake count at
293	     * registration, before it is itself persisted.
294	     */
295	    private int countNamesakes(String firstName, String lastName) {
296	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
297	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
298	            .count();
299	    }
300	
301	    /**
302	     * Find the existing owner, if any, that this new owner is a possible (soft) duplicate
303	     * of: one that occupies the same household (the same computed household id) but carries
304	     * a different telephone, so it is not a hard duplicate. When several match, the earliest
305	     * (lowest id) is chosen. An owner that belongs to no household (no household id), or one
306	     * that deliberately declared it shares a household, is never a suspected duplicate.
307	     */
308	    private Optional<Owner> findPossibleDuplicate(Owner owner) {
309	        String householdId = owner.getHouseholdId();
310	        if (householdId == null || owner.isDeclaredHouseholdMember()) {
311	            return Optional.empty();
312	        }
313	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
314	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
315	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
316	            .min(Comparator.comparing(Owner::getId));
317	    }
