213	        params.put("offset", pageable.getOffset());
214	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
215	            "SELECT id, first_name, last_name, address, city, telephone FROM owners ORDER BY id LIMIT :size OFFSET :offset",
216	            params,
217	            BeanPropertyRowMapper.newInstance(Owner.class));
218	        loadOwnersPetsAndVisits(owners);
219	        Long total = this.namedParameterJdbcTemplate.queryForObject(
220	            "SELECT COUNT(*) FROM owners",
221	            params,
222	            Long.class
223	        );
224	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
225	    }
