227		@Override
228		@Transactional
229		public void delete(Owner owner) throws DataAccessException {
230			Map<String, Object> ownerParams = new HashMap<>();
231			ownerParams.put("id", owner.getId());
232	        List<Pet> pets = owner.getPets();
233	        // cascade delete pets
234	        for (Pet pet : pets){
235	        	Map<String, Object> petParams = new HashMap<>();
236	        	petParams.put("id", pet.getId());
237	        	// cascade delete visits
238	        	List<Visit> visits = pet.getVisits();
239	            for (Visit visit : visits){
240	            	Map<String, Object> visitParams = new HashMap<>();
241	            	visitParams.put("id", visit.getId());
242	            	this.namedParameterJdbcTemplate.update("DELETE FROM visits WHERE id=:id", visitParams);
243	            }
244	            this.namedParameterJdbcTemplate.update("DELETE FROM pets WHERE id=:id", petParams);
245	        }
246	        this.namedParameterJdbcTemplate.update("DELETE FROM owners WHERE id=:id", ownerParams);
247		}
